(2270223, 310921, 4551, '<td valign="top">Was this shot with a mirror telephoto? Those telltale ''donutd'' made me think it was. Nice capture of the action. The orange chair pulls my eye away from the main subject though.</td>', 'Was this shot with a mirror telephoto? Those telltale ''donutd'' made me think it was. Nice capture of the action. The orange chair pulls my eye away from the main subject though.', '2006-03-29 14:23:34.000000', NULL, 1),
(2270225, 313151, 4551, '<td valign="top">Interesting idea but the image is a little flat on my screen.</td>', 'Interesting idea but the image is a little flat on my screen.', '2006-03-29 14:24:01.000000', NULL, 1),
(2270226, 311417, 4551, '<td valign="top">Technically a well executed shot! Very creative and not an easy one to set up.</td>', 'Technically a well executed shot! Very creative and not an easy one to set up.', '2006-03-29 14:24:38.000000', NULL, 1),
(2270229, 313216, 4551, '<td valign="top">Nice framing with the playground equipment. I don''t see full ''blacks'' on my monitor but otherwise good tonal range.</td>', 'Nice framing with the playground equipment. I don''t see full ''blacks'' on my monitor but otherwise good tonal range.', '2006-03-29 14:25:36.000000', NULL, 1),
(2270237, 312944, 16402, '<td valign="top">Not sure how you play with a flat ball, but at least it''s nice technically.</td>', 'Not sure how you play with a flat ball, but at least it''s nice technically.', '2006-03-29 14:27:49.000000', NULL, 1),
(2270248, 311535, 16402, '<td valign="top">Framing is weird (why is she half out of frame) and focus is off.</td>', 'Framing is weird (why is she half out of frame) and focus is off.', '2006-03-29 14:29:25.000000', NULL, 1),
(2270253, 311932, 16402, '<td valign="top">IMHO it''s always better to shoot people from the front where you can see their faces and expressions than the back.</td>', 'IMHO it''s always better to shoot people from the front where you can see their faces and expressions than the back.', '2006-03-29 14:30:36.000000', NULL, 1),
(2270257, 312743, 16402, '<td valign="top">Great job. Polished technically and meets the challenge.</td>', 'Great job. Polished technically and meets the challenge.', '2006-03-29 14:31:23.000000', NULL, 1),
(2270263, 313004, 16402, '<td valign="top">Really nice. Maybe a bit too centered but very well done otherwise.</td>', 'Really nice. Maybe a bit too centered but very well done otherwise.', '2006-03-29 14:32:45.000000', NULL, 1),
(2270268, 311938, 16402, '<td valign="top">Sorry don''t get it. What''s it got to do with challenge topic?</td>', 'Sorry don''t get it. What''s it got to do with challenge topic?', '2006-03-29 14:33:28.000000', NULL, 1),
