(2270291, 311031, 16402, '<td valign="top">Pushing the theme envelope a little too far for me and looks a lot like the 3rd place winner from Literary Adventure challenge.</td>', 'Pushing the theme envelope a little too far for me and looks a lot like the 3rd place winner from Literary Adventure challenge.', '2006-03-29 14:39:17.000000', NULL, 1),
(2270293, 312827, 4551, '<td valign="top">Interesting perspective. Even the out of focus pieces don''t bother me. Good tonal range.</td>', 'Interesting perspective. Even the out of focus pieces don''t bother me. Good tonal range.', '2006-03-29 14:40:04.000000', NULL, 1),
(2270294, 312507, 16402, '<td valign="top">Very interesting perspective but something off about it -- too much post processing (noise maybe)?</td>', 'Very interesting perspective but something off about it -- too much post processing (noise maybe)?', '2006-03-29 14:40:12.000000', NULL, 1),
(2270297, 313022, 54044, '<td valign="top">nice, very arty . i have bad memories after few of thees lol</td>', 'nice, very arty . i have bad memories after few of thees lol', '2006-03-29 14:40:19.000000', NULL, 1),
(2270298, 312791, 4551, '<td valign="top">Nice record shot of the historic event but otherwise a littel busy.</td>', 'Nice record shot of the historic event but otherwise a littel busy.', '2006-03-29 14:40:54.000000', NULL, 1),
(2270300, 311459, 54044, '<td valign="top">nice and simple straight to the point 8 from me</td>', 'nice and simple straight to the point 8 from me', '2006-03-29 14:41:24.000000', NULL, 1),
(2270307, 312605, 4551, '<td valign="top">Interesting that the car and signs are equally sharp. I suspect a good flash was used to stop the action. Good color and tonal reange. The signs are a little busy and compete with the subject but that''s what you had to work with.</td>', 'Interesting that the car and signs are equally sharp. I suspect a good flash was used to stop the action. Good color and tonal reange. The signs are a little busy and compete with the subject but that''s what you had to work with.', '2006-03-29 14:42:31.000000', NULL, 1),
(2270308, 313071, 16402, '<td valign="top">Not much techinically right about this: Blurry, overexposed, poor composition. Sorry.</td>', 'Not much techinically right about this: Blurry, overexposed, poor composition. Sorry.', '2006-03-29 14:42:34.000000', NULL, 1),
(2270310, 313049, 4551, '<td valign="top">Image is a little small to properly critique.</td>', 'Image is a little small to properly critique.', '2006-03-29 14:43:02.000000', NULL, 1),
(2270316, 313252, 4551, '<td valign="top">Nice capture at the playground. With the perceived motion I would have preferred a total blur. The vibrant green cjain covers draw your attention from the subject. I like the warm light coming from the back.</td>', 'Nice capture at the playground. With the perceived motion I would have preferred a total blur. The vibrant green cjain covers draw your attention from the subject. I like the warm light coming from the back.', '2006-03-29 14:44:55.000000', NULL, 1),
(2270318, 312783, 54044, '<td valign="top">wow ,theese eyes so much life in to them ,fab image 10</td>', 'wow ,theese eyes so much life in to them ,fab image 10', '2006-03-29 14:45:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2270321, 312370, 4551, '<td valign="top">Interesting comparison of size. Good color and sharpness</td>', 'Interesting comparison of size. Good color and sharpness', '2006-03-29 14:45:36.000000', NULL, 1),
(2270322, 312208, 54044, '<td valign="top">one game i cant understand , Golf nice image tho</td>', 'one game i cant understand , Golf nice image tho', '2006-03-29 14:46:21.000000', NULL, 1),
(2270327, 313109, 4551, '<td valign="top">Nice placement of the seagulls in the foreground of "their''" beach. Not sure the subtle frame is needed.</td>', 'Nice placement of the seagulls in the foreground of "their''" beach. Not sure the subtle frame is needed.', '2006-03-29 14:46:53.000000', NULL, 1),
(2270332, 312728, 54044, '<td valign="top">this is nice all tho the image quality is not best</td>', 'this is nice all tho the image quality is not best', '2006-03-29 14:47:30.000000', NULL, 1),
(2270333, 312868, 55881, '<td valign="top">Great emotions captured! However, I would like to have eye contact with one of the center child instead of the one on top left. :) 8 out of 10!</td>', 'Great emotions captured! However, I would like to have eye contact with one of the center child instead of the one on top left. :) 8 out of 10!', '2006-03-29 14:47:41.000000', NULL, 1),
(2270335, 313187, 4551, '<td valign="top">Cute shot. Since the brown dog''s eyes were covered, it took a minute to see what was actually going on. Nice combination of flash and available light.</td>', 'Cute shot. Since the brown dog''s eyes were covered, it took a minute to see what was actually going on. Nice combination of flash and available light.', '2006-03-29 14:47:56.000000', NULL, 1),
(2270338, 312235, 4551, '<td valign="top">Colorful chips. The out-of-focus cards tend to distract more than add to the effect. May have been just as effective with the cards face down but sharper.</td>', 'Colorful chips. The out-of-focus cards tend to distract more than add to the effect. May have been just as effective with the cards face down but sharper.', '2006-03-29 14:49:02.000000', NULL, 1),
(2270342, 312629, 4551, '<td valign="top">Cute recrd shot at the playground. Cropping may have made better use of space in the frame. As presented, right half is void of any purpose.</td>', 'Cute recrd shot at the playground. Cropping may have made better use of space in the frame. As presented, right half is void of any purpose.', '2006-03-29 14:50:00.000000', NULL, 1),
(2270343, 313292, 54044, '<td valign="top">i have been climbing for years and have never seen anyone to do it with flip flops on lol ,nice idea</td>', 'i have been climbing for years and have never seen anyone to do it with flip flops on lol ,nice idea', '2006-03-29 14:50:01.000000', NULL, 1),
(2270347, 310023, 4551, '<td valign="top">Interesting perspective. Just wish the thumb was a little sharper</td>', 'Interesting perspective. Just wish the thumb was a little sharper', '2006-03-29 14:50:36.000000', NULL, 1),
(2270351, 312759, 4551, '<td valign="top">Good vantage point. Excellent use of light. Good shadow detail and sharpness. Well done!</td>', 'Good vantage point. Excellent use of light. Good shadow detail and sharpness. Well done!', '2006-03-29 14:51:21.000000', NULL, 1),
(2270353, 311508, 54044, '<td valign="top">lol ,this is nice i love it</td>', 'lol ,this is nice i love it', '2006-03-29 14:51:37.000000', NULL, 1),
(2270355, 312761, 4551, '<td valign="top">The expressions make the shot. Good sharpness and shadow detail as well as cropping</td>', 'The expressions make the shot. Good sharpness and shadow detail as well as cropping', '2006-03-29 14:52:07.000000', NULL, 1),
(2270357, 311331, 55881, '<td valign="top">There''s no eye contact nor facial expression to be seen. I''m giving a 4.</td>', 'There''s no eye contact nor facial expression to be seen. I''m giving a 4.', '2006-03-29 14:52:12.000000', NULL, 1),
(2270362, 313324, 55881, '<td valign="top">Interesting shot!</td>', 'Interesting shot!', '2006-03-29 14:52:32.000000', NULL, 1),
(2270364, 313215, 4551, '<td valign="top">Sharp but a little gray due to lack of major white areas. My eyes are drawn to the white shoes right off.</td>', 'Sharp but a little gray due to lack of major white areas. My eyes are drawn to the white shoes right off.', '2006-03-29 14:53:23.000000', NULL, 1),
(2270366, 313018, 55881, '<td valign="top">Nice portrait shot. 10 out of 10!</td>', 'Nice portrait shot. 10 out of 10!', '2006-03-29 14:53:28.000000', NULL, 1),
(2270371, 312537, 4551, '<td valign="top">Nice use of the colorful balls for framing.</td>', 'Nice use of the colorful balls for framing.', '2006-03-29 14:53:55.000000', NULL, 1),
(2270373, 311508, 55881, '<td valign="top">Too dark, however interesting perspective.</td>', 'Too dark, however interesting perspective.', '2006-03-29 14:54:08.000000', NULL, 1),
(2270377, 312629, 55881, '<td valign="top">This kid is cute!</td>', 'This kid is cute!', '2006-03-29 14:54:27.000000', NULL, 1),
(2270380, 312036, 4551, '<td valign="top">With the closeness of the two subjects, perhaps this would be dtronger as a vertical. May want to lessen some of the sky so that horizon isn''t as close to the middle.</td>', 'With the closeness of the two subjects, perhaps this would be dtronger as a vertical. May want to lessen some of the sky so that horizon isn''t as close to the middle.', '2006-03-29 14:55:01.000000', NULL, 1),
(2270382, 313248, 54044, '<td valign="top">i am sory but i must say ,is this a video camera shot ?The pixalage is so in your face, no offence</td>', 'i am sory but i must say ,is this a video camera shot ?The pixalage is so in your face, no offence', '2006-03-29 14:55:06.000000', NULL, 1),
(2270386, 313145, 4551, '<td valign="top">Good sharpness and tonal range. Placement of subject adds to title.</td>', 'Good sharpness and tonal range. Placement of subject adds to title.', '2006-03-29 14:55:46.000000', NULL, 1),
(2270390, 310755, 4551, '<td valign="top">I like the perspective from inside the doll house. The glazed windows add a heightened mystery to who is seen through the open pane. Nicely done</td>', 'I like the perspective from inside the doll house. The glazed windows add a heightened mystery to who is seen through the open pane. Nicely done', '2006-03-29 14:56:59.000000', NULL, 1),
(2270392, 311606, 54044, '<td valign="top">This is cool love it</td>', 'This is cool love it', '2006-03-29 14:57:18.000000', NULL, 1),
(2270396, 312714, 4551, '<td valign="top">Cute abstract use of vegetables. Did you also try one on a plate to better resemble a face?</td>', 'Cute abstract use of vegetables. Did you also try one on a plate to better resemble a face?', '2006-03-29 14:57:46.000000', NULL, 1),
(2270400, 312053, 4551, '<td valign="top">Pure joy! Nicely done. Good tonal range and sharpness. The expressions sell this shot.</td>', 'Pure joy! Nicely done. Good tonal range and sharpness. The expressions sell this shot.', '2006-03-29 14:58:28.000000', NULL, 1),
(2270404, 313071, 4551, '<td valign="top">Hmmmm. A little burned out to read the picture well. But I give you credit for the effort.</td>', 'Hmmmm. A little burned out to read the picture well. But I give you credit for the effort.', '2006-03-29 14:59:10.000000', NULL, 1),
(2270407, 312822, 4551, '<td valign="top">With the spread of the hands it is always a difficult question to decide which hand should be the sharpest. My preference would go to the one closest to the viewer or somewhere in the middle, sacrificing overall critical sharpness.</td>', 'With the spread of the hands it is always a difficult question to decide which hand should be the sharpest. My preference would go to the one closest to the viewer or somewhere in the middle, sacrificing overall critical sharpness.', '2006-03-29 15:00:27.000000', NULL, 1),
