INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2271818, 311566, 4551, '<td valign="top">A little washed out due to overexposure. Lots of open space. My eyes want to go from person to person without knowing where the point of interest is.</td>', 'A little washed out due to overexposure. Lots of open space. My eyes want to go from person to person without knowing where the point of interest is.', '2006-03-29 22:36:33.000000', NULL, 1),
(2271820, 311455, 4551, '<td valign="top">Would be better if the background were more out of focus. Good tonal range and sharpness.</td>', 'Would be better if the background were more out of focus. Good tonal range and sharpness.', '2006-03-29 22:37:39.000000', NULL, 1),
(2271823, 313199, 4551, '<td valign="top">Interesting contrast in ages and dress. Cropped alittle close but maybe it was necesary to keep out distracting bits. Good color and tone.</td>', 'Interesting contrast in ages and dress. Cropped alittle close but maybe it was necesary to keep out distracting bits. Good color and tone.', '2006-03-29 22:38:46.000000', NULL, 1),
(2271825, 312762, 4551, '<td valign="top">Cute shot. Good timing  on the action but a little too small to properly critique.</td>', 'Cute shot. Good timing  on the action but a little too small to properly critique.', '2006-03-29 22:39:24.000000', NULL, 1),
(2271826, 311031, 54811, '<td valign="top">great picture, but just don''t see it fitting into this contest...</td>', 'great picture, but just don''t see it fitting into this contest...', '2006-03-29 22:40:00.000000', NULL, 1),
(2271827, 312390, 4551, '<td valign="top">A little hard to understand what the photographer intended.</td>', 'A little hard to understand what the photographer intended.', '2006-03-29 22:40:09.000000', NULL, 1),
(2271829, 311438, 4551, '<td valign="top">Good timing for the stop action off the ground.</td>', 'Good timing for the stop action off the ground.', '2006-03-29 22:40:59.000000', NULL, 1),
(2271831, 310799, 4551, '<td valign="top">Not sure this is really ''playtime'' as these guys look like all business. Technically excellent quality shot. Great color, sharpness and tonal range---just doesn''t seem to fit the category.</td>', 'Not sure this is really ''playtime'' as these guys look like all business. Technically excellent quality shot. Great color, sharpness and tonal range---just doesn''t seem to fit the category.', '2006-03-29 22:42:21.000000', NULL, 1),
(2271833, 310562, 4551, '<td valign="top">Good use of foreground person to add depth to the scene. Too bad the feet had to be cut off.</td>', 'Good use of foreground person to add depth to the scene. Too bad the feet had to be cut off.', '2006-03-29 22:42:56.000000', NULL, 1),
(2271836, 312743, 4551, '<td valign="top">Nice sharpness and illusion of depth to the picture. Seems to be underexposed just a tad.</td>', 'Nice sharpness and illusion of depth to the picture. Seems to be underexposed just a tad.', '2006-03-29 22:44:13.000000', NULL, 1),
(2271838, 311008, 4551, '<td valign="top">Nice composition and tonal qualities. <br/>Would have prefered to see the whole person.<br/>Good work!</td>', 'Nice composition and tonal qualities. Would have prefered to see the whole person.Good work!', '2006-03-29 22:45:27.000000', NULL, 1),
(2271839, 312356, 4551, '<td valign="top">Studio quality color, tonal range and sharpness but perhaps a little too much ''white'' space to the right of the frame. Flipping the image from left to right would keep my eyes in the frame for alonger time.</td>', 'Studio quality color, tonal range and sharpness but perhaps a little too much ''white'' space to the right of the frame. Flipping the image from left to right would keep my eyes in the frame for alonger time.', '2006-03-29 22:46:59.000000', NULL, 1),
(2271840, 312616, 4551, '<td valign="top">Nice time exposure of the flaming rope. Not too sure he is "playing" here.</td>', 'Nice time exposure of the flaming rope. Not too sure he is "playing" here.', '2006-03-29 22:47:47.000000', NULL, 1),
(2271894, 311739, 46448, '<td valign="top">This is nice high quality image, I like the composition, the exposure is right on. This had to be taken with a pretty fast lens. Good job I hope this places well for you!</td>', 'This is nice high quality image, I like the composition, the exposure is right on. This had to be taken with a pretty fast lens. Good job I hope this places well for you!', '2006-03-29 23:26:01.000000', NULL, 1),
(2271909, 313215, 29269, '<td valign="top">I would have preferred to see more faces. Moreover, the black&amp;white is kind of dull in this photo. It seems that the 50% of the photo is within +/- 5% of the same shade of gray. You could have played more with different color channels and selectively (color-wise) shift hues and brightness to achieve more dynamic photo.</td>', 'I would have preferred to see more faces. Moreover, the black&white is kind of dull in this photo. It seems that the 50% of the photo is within +/- 5% of the same shade of gray. You could have played more with different color channels and selectively (color-wise) shift hues and brightness to achieve more dynamic photo.', '2006-03-29 23:35:46.000000', NULL, 1),
(2271914, 311008, 29269, '<td valign="top">Nice perspective makes it different from other park snapshots. This extra effort will probably make a whole point difference in the final standings. More dynamic range would have helped - there are no significant dark areas on the photo and that makes it duller than it had to be.</td>', 'Nice perspective makes it different from other park snapshots. This extra effort will probably make a whole point difference in the final standings. More dynamic range would have helped - there are no significant dark areas on the photo and that makes it duller than it had to be.', '2006-03-29 23:37:23.000000', NULL, 1),
(2271927, 312605, 46448, '<td valign="top">I dunno man, this went from playtime to ah man this sux crash time:) Great picture though. Go team olympus:)</td>', 'I dunno man, this went from playtime to ah man this sux crash time:) Great picture though. Go team olympus:)', '2006-03-29 23:50:38.000000', NULL, 1),
(2271931, 312213, 36403, '<td valign="top">Nice action shot.</td>', 'Nice action shot.', '2006-03-29 23:50:59.000000', NULL, 1),
