(2291326, 312868, 28742, '<td valign="top">Goodman!!!!!!!</td>', 'Goodman!!!!!!!', '2006-04-06 03:57:41.000000', NULL, 0),
(2291331, 311459, 28742, '<td valign="top">This image <i>sings</i> to me. A song of joy and sadness. Of dryness and wetness. Of boredom and overcoming of boredom. It''s a visual metaphor for the beginning of life and the sunset years. It''s confusing and entertaining. It has changed my life. I will never look at things again. ...the same, I mean.<br/> <br/>...Yanking yer chain, AH - trying to see what it takes to get a click from you. ;-) It is an excellent image and I wish I could comment with seriousness, but it''s not in my nature. I honestly do like it and congratulate you on a very strong finish. <br/> <br/>-Ken</td>', 'This image sings to me. A song of joy and sadness. Of dryness and wetness. Of boredom and overcoming of boredom. It''s a visual metaphor for the beginning of life and the sunset years. It''s confusing and entertaining. It has changed my life. I will never look at things again. ...the same, I mean. ...Yanking yer chain, AH - trying to see what it takes to get a click from you. ;-) It is an excellent image and I wish I could comment with seriousness, but it''s not in my nature. I honestly do like it and congratulate you on a very strong finish.  -Ken', '2006-04-06 04:07:00.000000', NULL, 0),
(2291361, 312868, 39993, '<td valign="top">Congrats!<br/>(Eish, you make it look so easy :)</td>', 'Congrats!(Eish, you make it look so easy :)', '2006-04-06 04:31:58.000000', NULL, 0),
(2291448, 312827, 35720, '<td valign="top">Congratulations on your first ribbon in your first submission. It''s a well deserved ribbon for a wonderful photo.</td>', 'Congratulations on your first ribbon in your first submission. It''s a well deserved ribbon for a wonderful photo.', '2006-04-06 06:30:14.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2291508, 310755, 14603, '<td valign="top">I totally agree with you that the dirty windows and the contrast in focus created with the missing window and the small gap really add so much to this image.<br/> <br/>Great work as always.<br/> <br/>Congratulations.<br/></td>', 'I totally agree with you that the dirty windows and the contrast in focus created with the missing window and the small gap really add so much to this image. Great work as always. Congratulations.', '2006-04-06 07:53:21.000000', NULL, 0),
(2291728, 313071, 55840, '<td valign="top">Have to agree with everyone.  Deserved a low score.  Don''t know what I was quite thinking entering it but I really kinda liked the artistic look of the blur and the washed out.  Maybe it is because I have never shot anything like this that I thought it was different and unique.  It reminded me of a painting.  But now the more I look at it, I see it from a professionals point of view and see all the technical errors. I figure though I can only get better from here and now I am beginning to see what others vote higher scores on so that helps too!</td>', 'Have to agree with everyone.  Deserved a low score.  Don''t know what I was quite thinking entering it but I really kinda liked the artistic look of the blur and the washed out.  Maybe it is because I have never shot anything like this that I thought it was different and unique.  It reminded me of a painting.  But now the more I look at it, I see it from a professionals point of view and see all the technical errors. I figure though I can only get better from here and now I am beginning to see what others vote higher scores on so that helps too!', '2006-04-06 09:59:36.000000', NULL, 0),
(2291766, 313355, 26255, '<td valign="top">I agree with the other comments, the composition could be helped by having the little girl looking at what is in her hands... this would help better convey a sense of "play".  As it stands, the image itself could be helped with a better crop.  By cropping out the bow and "wheelhouse" of the "ship", more focus would be placed on your subject.  Since the girl <b>and</b> the "wheelhouse" dominate the image, they are both competing for the viewers attention.  Also try playing around with levels to add more "pop" to the image.</td>', 'I agree with the other comments, the composition could be helped by having the little girl looking at what is in her hands... this would help better convey a sense of "play".  As it stands, the image itself could be helped with a better crop.  By cropping out the bow and "wheelhouse" of the "ship", more focus would be placed on your subject.  Since the girl and the "wheelhouse" dominate the image, they are both competing for the viewers attention.  Also try playing around with levels to add more "pop" to the image.', '2006-04-06 10:17:58.000000', NULL, 0),
(2291815, 312868, 47249, '<td valign="top">Congrats goodman! I watched your portfolio...I love your photos!!<br/><br/><i>Message edited by author 2006-04-06 10:47:57.</i></td>', 'Congrats goodman! I watched your portfolio...I love your photos!!', '2006-04-06 10:59:49.000000', '2006-04-06 11:47:57.000000', 0),
(2291842, 312827, 47249, '<td valign="top">Thanks everyone, indeed!! I registered to this great community some months ago, but only now I have decided to partecipate. I''m Italian, so I hope you forgive my awful english language, I would like to say a lot of things, but...''too difficult'' :))<br/>Thanks again!</td>', 'Thanks everyone, indeed!! I registered to this great community some months ago, but only now I have decided to partecipate. I''m Italian, so I hope you forgive my awful english language, I would like to say a lot of things, but...''too difficult'' :))Thanks again!', '2006-04-06 11:15:51.000000', NULL, 0),
